const input = $input.first().json;
const body = input.body || input;

const email = String(body.email || '').trim().toLowerCase();
const agencies = Array.isArray(body.agencies) ? body.agencies : [];
const topics = Array.isArray(body.topics) ? body.topics : [];

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

if (!emailRegex.test(email)) {
  throw new Error('Invalid email address');
}

const cleanAgencies = agencies
  .map(a => String(a || '').trim().toLowerCase())
  .filter(a => /^[a-z0-9-]+$/.test(a))
  .slice(0, 25);

const allowedTopics = new Set([
  'animal welfare',
  'wildlife',
  'livestock',
  'laboratory animals',
  'marine mammals',
  'endangered species',
  'animal disease',
  'public comments'
]);

const cleanTopics = topics
  .map(t => String(t || '').trim().toLowerCase())
  .filter(t => allowedTopics.has(t))
  .slice(0, 25);

return [
  {
    json: {
      email,
      agencies: cleanAgencies,
      topics: cleanTopics,
      agenciesJson: JSON.stringify(cleanAgencies),
      topicsJson: JSON.stringify(cleanTopics)
    }
  }
];

const input = $input.first().json;
const body = input.body || input;

const date = String(body.date || '').trim();
const agencySlug = String(body.agency_slug || '').trim().toLowerCase();
const documentType = String(body.document_type || '').trim().toLowerCase();
const actionability = String(body.actionability || '').trim().toLowerCase();
const deadlineStatus = String(body.deadline_status || '').trim().toLowerCase();

if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  throw new Error('Invalid date. Expected YYYY-MM-DD');
}

if (agencySlug && !/^[a-z0-9-]+$/.test(agencySlug)) {
  throw new Error('Invalid agency_slug');
}

const allowedDocumentTypes = new Set(['notice', 'rule', 'proposed rule', 'presidential document', '']);
const allowedActionability = new Set(['public comment open', 'urgent', 'monitoring only', 'action available', '']);
const allowedDeadlineStatus = new Set(['open', 'approaching', 'closed', 'none', '']);

if (!allowedDocumentTypes.has(documentType)) {
  throw new Error('Invalid document_type');
}

if (!allowedActionability.has(actionability)) {
  throw new Error('Invalid actionability');
}

if (!allowedDeadlineStatus.has(deadlineStatus)) {
  throw new Error('Invalid deadline_status');
}

return [
  {
    json: {
      date,
      agency_slug: agencySlug,
      document_type: documentType,
      actionability,
      deadline_status: deadlineStatus
    }
  }
];

const raw = $input.first().json;

const agencies = Array.isArray(raw)
  ? raw
  : Array.isArray(raw.results)
    ? raw.results
    : Array.isArray(raw.agencies)
      ? raw.agencies
      : [];

const prioritySlugs = [
  'animal-and-plant-health-inspection-service',
  'food-and-drug-administration',
  'fish-and-wildlife-service',
  'national-oceanic-and-atmospheric-administration',
  'national-institutes-of-health',
  'environmental-protection-agency',
  'agriculture-department',
  'interior-department',
  'food-safety-and-inspection-service'
];

const formatted = agencies
  .map(a => ({
    name: a.name || a.display_name || a.title || '',
    slug: a.slug || '',
    url: a.url || (a.slug ? `https://www.federalregister.gov/api/v1/agencies/${a.slug}` : '')
  }))
  .filter(a => a.name && a.slug);

formatted.sort((a, b) => {
  const ai = prioritySlugs.indexOf(a.slug);
  const bi = prioritySlugs.indexOf(b.slug);

  if (ai !== -1 && bi !== -1) return ai - bi;
  if (ai !== -1) return -1;
  if (bi !== -1) return 1;
  return a.name.localeCompare(b.name);
});

return [
  {
    json: {
      success: true,
      count: formatted.length,
      agencies: formatted
    }
  }
];

const input = $input.first().json;
const query = input.query || {};
const body = input.body || {};
const slug = String(query.slug || body.slug || input.slug || '').trim().toLowerCase();

if (!slug || !/^[a-z0-9-]+$/.test(slug)) {
  throw new Error('Invalid or missing slug. Use /webhook/agency-detail?slug=animal-and-plant-health-inspection-service');
}

return [{ json: { slug } }];

const notices = $input.all().map(item => item.json);

return [
  {
    json: {
      success: true,
      date: $('Validate Calendar Request').first().json.date,
      count: notices.length,
      notices
    }
  }
];
